('3152c774-e3a2-4e07-a8d2-9098a15fa0e3', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "f04f0ca9-e5c2-4d32-a554-d764c25f0987", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "c4d0538d-8cb8-4f55-b344-8fdada40f522", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "babca1fe-b68e-438f-a926-6f0f69536918", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "d48b3e1a-2612-4aab-a800-fdde94935973", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "bdf2ae51-0779-48c3-a3dc-b141df64be06", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "e74a0c05-a84c-4dc4-8c73-b2c1a1d8e181", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "860ba005-f07b-45ad-bb70-e65d8fe51d0a", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "de86ed19-76d3-4782-8d4d-3d037afa412c", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "8bb3dc43-31d7-42f3-a78c-b10e969e874c", "text": "Igaz", "isCorrect": true}, {"id": "a5770a19-d3c0-4574-9317-69a9d45903ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "769df0fc-1b60-4676-8fea-ad814d0c6ef9", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "a4d50fe0-2a18-46d4-a109-ab49c0d4891c", "text": "Igaz", "isCorrect": true}, {"id": "40f6b2ac-19c7-4d45-b0f4-c803167959e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32dac7e7-414b-418d-8c05-62c3c8